def test_arrangement_imports_installed_package() -> None:
    """With the wheel installed, `pytest --import-mode=importlib` imports it, not the source."""
    installed = [
        distribution
        for distribution in distributions(name='{{ CONA }}')
        if distribution.read_text('INSTALLER')
    ]
    if not installed:
        skip('{{ CONA }} is not installed')
    location = str(installed[0].locate_file('{{ module }}/__init__.py'))
    assert import_module('{{ module }}').__file__ == location
